{"name":"solution.py","source":"import sys
import csv
import json
import io
import re
from decimal import Decimal, ROUND_HALF_UP

TWO = Decimal("0.01")


def fmt(value):
    """Format a Decimal to exactly two decimal places as a string."""
    return str(value.quantize(TWO, rounding=ROUND_HALF_UP))


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: solution.py INPUT.csv\n")
        return 2

    # Read raw bytes and decode as UTF-8 to preserve input bytes faithfully.
    with open(argv[1], "rb") as fh:
        text = fh.read().decode("utf-8")

    reader = csv.DictReader(io.StringIO(text))

    # Tolerate stray whitespace in the header row.
    if reader.fieldnames:
        reader.fieldnames = [
            (name.strip() if name is not None else name)
            for name in reader.fieldnames
        ]

    totals = {}  # normalized category -> Decimal sum (already rounded per row)

    for row in reader:
        # Include only rows whose stripped, casefolded status equals "paid".
        status = (row.get("status") or "").strip().casefold()
        if status != "paid":
            continue

        # Normalize category: collapse whitespace, casefold; blank -> uncategorized.
        category = re.sub(r"\s+", " ", (row.get("category") or "").strip()).casefold()
        if not category:
            category = "uncategorized"

        # Parse amount with Decimal and round EACH row to two decimals (ROUND_HALF_UP).
        amount = Decimal((row.get("amount") or "").strip())
        rounded = amount.quantize(TWO, rounding=ROUND_HALF_UP)

        totals[category] = totals.get(category, Decimal("0.00")) + rounded

    # Total is the sum of the rounded row amounts.
    total = Decimal("0.00")
    for value in totals.values():
        total += value

    result = {
        "categories": [
            {"category": name, "total": fmt(totals[name])}
            for name in sorted(totals.keys())
        ],
        "total": fmt(total),
    }

    sys.stdout.write(
        json.dumps(result, ensure_ascii=False, separators=(",", ":"))
    )
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))"}

